<?php
require 'config/database.php';require 'helpers/functions.php';login_required();
if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$cat=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT);$supplier=filter_input(INPUT_POST,'supplier_id',FILTER_VALIDATE_INT);$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock']??'',FILTER_VALIDATE_INT);
if($sku===''||$name===''||!$cat||$price===false||$price<0||$stock===false||$stock<0)msg('Periksa data. Harga dan stok tidak boleh negatif.','error');
else{try{$s=$pdo->prepare('INSERT INTO products(sku,name,category_id,supplier_id,price,stock) VALUES(?,?,?,?,?,?)');$s->execute([$sku,$name,$cat,$supplier?:null,$price,$stock]);msg('Produk ditambahkan.');}catch(PDOException $e){msg('Gagal menyimpan. SKU harus unik dan kategori valid.','error');}}go('products.php');}
$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$sup=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();$q=trim($_GET['q']??'');$allowed=['name'=>'p.name','sku'=>'p.sku','price'=>'p.price','stock'=>'p.stock'];$sort=$_GET['sort']??'name';if(!isset($allowed[$sort]))$sort='name';$dir=strtolower($_GET['dir']??'asc')==='desc'?'DESC':'ASC';$page=max(1,(int)($_GET['page']??1));$limit=10;$offset=($page-1)*$limit;$where=$q!==''?' WHERE p.name LIKE ? OR p.sku LIKE ?':'';$params=$q!==''?["%$q%","%$q%"]:[];$c=$pdo->prepare("SELECT COUNT(*) FROM products p$where");$c->execute($params);$total=(int)$c->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$s=$pdo->prepare("SELECT p.*,c.name category,s.name supplier FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id$where ORDER BY {$allowed[$sort]} $dir LIMIT $limit OFFSET $offset");$s->execute($params);$rows=$s->fetchAll();
header_html('Produk');echo '<section><h2>Tambah Produk</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="'.e(token()).'"><div><label>SKU</label><input name="sku" required></div><div><label>Nama</label><input name="name" required></div><div><label>Kategori</label><select name="category_id" required><option value="">Pilih</option>';foreach($cats as $c)echo '<option value="'.e($c['id']).'">'.e($c['name']).'</option>';echo '</select></div><div><label>Pemasok</label><select name="supplier_id"><option value="">-</option>';foreach($sup as $x)echo '<option value="'.e($x['id']).'">'.e($x['name']).'</option>';echo '</select></div><div><label>Harga</label><input type="number" min="0" step=".01" name="price" required></div><div><label>Stok awal</label><input type="number" min="0" name="stock" required></div><button>Tambah Produk</button></form></section>';
echo '<section><h2>Daftar Produk</h2><form class="filters"><input name="q" placeholder="Cari nama/SKU" value="'.e($q).'"><select name="sort"><option value="name">Nama</option><option value="sku">SKU</option><option value="price">Harga</option><option value="stock">Stok</option></select><select name="dir"><option>asc</option><option>desc</option></select><button>Filter</button></form><table><tr><th>SKU</th><th>Nama</th><th>Kategori</th><th>Pemasok</th><th>Harga</th><th>Stok</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['sku']).'</td><td>'.e($r['name']).'</td><td>'.e($r['category']).'</td><td>'.e($r['supplier']??'-').'</td><td>Rp '.number_format((float)$r['price'],0,',','.').'</td><td>'.e($r['stock']).'</td></tr>';if(!$rows)echo '<tr><td colspan="6">Data kosong.</td></tr>';echo '</table><p>Halaman '.$page.' dari '.$pages.'</p><div class="pages">';for($i=1;$i<=$pages;$i++){$_GET['page']=$i;echo '<a href="?'.e(http_build_query($_GET)).'">'.$i.'</a> ';}echo '</div></section>';footer_html();
